local config = {
  ui_story_5052_50520101_1_dialog_content = "\"...\"",
  ui_story_5052_50520101_2_dialog_content = "Greetings, PlayerName.",
  ui_story_5052_50520101_3_dialog_content = "Welcome...",
  ui_story_5052_50520101_4_dialog_content = "... to the Hall of Truth.",
  ui_story_5052_50520101_5_option_content = "Who's there?",
  ui_story_5052_50520101_6_dialog_content = "Hello? Is someone there?",
  ui_story_5052_50520101_7_dialog_content = "Weird. I could've sworn I heard someone talking just now...",
  ui_story_5052_50520101_8_dialog_content = "How did I end up here anyway? Last I remember, I was walking through the streets of Umbraton.",
  ui_story_5052_50520101_9_option_content = "Where am I?",
  ui_story_5052_50520101_10_dialog_content = "This place feels kind of familiar, like one of the <color=#FFB400>True Order's</color> gathering places.",
  ui_story_5052_50520101_11_dialog_content = "How'd I end up here, anyway? Last I remember, I was walking through the streets of Umbraton.",
  ui_story_5052_50520101_12_dialog_content = "<color=#e8d9bb>Ten minutes ago</color>",
  ui_story_5052_50520101_13_dialog_content = "Hello, PlayerName.",
  ui_story_5052_50520101_14_dialog_content = "Oh, hey, Eicy! Getting some shopping done too? Which store are you gonna clean out today?",
  ui_story_5052_50520101_15_dialog_content = "Actually, there's a place nearby that I'd really like to show you.",
  ui_story_5052_50520101_16_dialog_content = "Do you have some time to check it out?",
  ui_story_5052_50520101_17_dialog_content = "Sure, I've got nothing else going on right now.",
  ui_story_5052_50520101_18_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5052_50520101_19_dialog_content = "And then, she showed me her right eye, the Hollow Gaze.",
  ui_story_5052_50520101_20_dialog_content = "Oh, I see now.",
  ui_story_5052_50520101_21_dialog_content = "So it was just a simple mind-control, and I thought I was sleepwalking!",
  ui_story_5052_50520101_22_dialog_content = "But why would she bring me here?",
  ui_story_5052_50520101_23_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_5052_50520101_24_dialog_content = "Hmm? What was that?",
  ui_story_5052_50520101_25_dialog_content = "This <color=#FFB400>book</color> looks familiar too... Have I seen it somewhere before?",
  ui_story_5052_50520101_26_dialog_content = "Oh, right! This is the book that <color=#FFB400>Victoria</color> is always carrying around!",
  ui_story_5052_50520101_27_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_5052_50520101_28_dialog_content = "The pages are turning by themselves. Let me see what's on the pages.",
  ui_story_5052_50520101_29_dialog_content = "Hmmm, some notes were written to me.",
  ui_story_5052_50520101_30_dialog_content = "\"Navigator, by now you should have stumbled upon this message.\"",
  ui_story_5052_50520101_31_dialog_content = "\"You are about to face a very unique <color=#FFB400>trial</color>, the likes of which you have never before experienced.\"",
  ui_story_5052_50520101_32_dialog_content = "\"But rest assured, the <color=#FFB400>Black Tome</color> shows kindness to all of its readers...\"",
  ui_story_5052_50520101_33_dialog_content = "\"You must embrace change if you wish to succeed, Navigator.\"",
  ui_story_5052_50520101_34_dialog_content = "\"This new trial is challenging yet quite enjoyable. Even I could not reach its glorious conclusion.\"",
  ui_story_5052_50520101_35_dialog_content = "\"We must face each of its tests with the utmost devotion and submissiveness...\"",
  ui_story_5052_50520101_36_dialog_content = "\"Do not let these guys confuse you, PlayerName. This trial is not nearly as complicated as they make it seem.\"",
  ui_story_5052_50520101_37_dialog_content = "\"This is nothing more than a passing whim of destiny, one that has long since been determined.\"",
  ui_story_5052_50520101_38_dialog_content = "\"Just remember...\"",
  ui_story_5052_50520101_39_dialog_content = "\"Burn after reading.\"",
  ui_story_5052_50520101_40_dialog_content = "\"Huh? Why do I have to leave him a message too?",
  ui_story_5052_50520101_41_dialog_content = "\"Just write something for me, will you? It's not like PlayerName will actually read it or anything.\"",
  ui_story_5052_50520101_42_dialog_content = "\"You guys are great at making up cryptic stuff that nobody understands. Just go with something like that!\"",
  ui_story_5052_50520101_43_dialog_content = "\"Besides, it's time for my afternoon tea. Buh-bye!\"",
  ui_story_5052_50520101_44_dialog_content = "...",
  ui_story_5052_50520101_45_option_content = "I completely understood everything.",
  ui_story_5052_50520101_46_dialog_content = "Their words are as vague and confusing as ever, but I think I got the gist of things.",
  ui_story_5052_50520101_47_dialog_content = "I'm here to go through some sort of <color=#FFB400>trial</color>, right?",
  ui_story_5052_50520101_48_dialog_content = "<color=#e8d9bb>The book's pages begin to turn once again. Suddenly, words begin to appear on a blank page...</color>",
  ui_story_5052_50520101_49_dialog_content = "\"Correct.\"",
  ui_story_5052_50520101_50_option_content = "That sure was a bunch of nonsense.",
  ui_story_5052_50520101_51_dialog_content = "For all their pointless words, they may as well have said nothing at all.",
  ui_story_5052_50520101_52_dialog_content = "Anyway, what kind of <color=#FFB400>trial</color> are they talking about? What do they mean by \"the likes of which I have never before experienced\"?",
  ui_story_5052_50520101_53_dialog_content = "<color=#e8d9bb>The book's pages begin to turn once again. Suddenly, words begin to appear on a blank page...</color>",
  ui_story_5052_50520101_54_dialog_content = "\"It means it is extremely different.\"",
  ui_story_5052_50520101_55_dialog_content = "?!",
  ui_story_5052_50520101_56_dialog_content = "I-Is this thing writing to me?!",
  ui_story_5052_50520101_57_dialog_content = "\"Hello, PlayerName.\"",
  ui_story_5052_50520101_58_dialog_content = "Hello?",
  ui_story_5052_50520101_59_dialog_content = "Wait, can this book actually hear me, or do I have to write my responses in it?",
  ui_story_5052_50520101_60_dialog_content = "\"I can hear you.\"",
  ui_story_5052_50520101_61_dialog_content = "This is so weird...",
  ui_story_5052_50520101_62_option_content = "What's going on here?",
  ui_story_5052_50520101_63_dialog_content = "\"I have been expecting you for a long time now.\"",
  ui_story_5052_50520101_64_dialog_content = "\"The Truth's disciples have prepared a number of <color=#FFB400>trials</color> for you to overcome. I trust that you are ready?\"",
  ui_story_5052_50520101_65_option_content = "What's your name?",
  ui_story_5052_50520101_66_dialog_content = "\"I have no name, yet all things are done in my name.\"",
  ui_story_5052_50520101_67_dialog_content = "\"For without a name, we are all the same.\"",
  ui_story_5052_50520101_68_dialog_content = "So what's your purpose here?",
  ui_story_5052_50520101_69_dialog_content = "\"At this very moment, my purpose is to share a unique <color=#FFB400>trial</color> with you.\"",
  ui_story_5052_50520101_70_option_content = "(Try using psychic abilities)",
  ui_story_5052_50520101_71_dialog_content = "\"Do not attempt to plumb the depths of my consciousness, Caelestite. I am far more than what I appear to be.\"",
  ui_story_5052_50520101_72_dialog_content = "(Crap, it noticed!)",
  ui_story_5052_50520101_73_dialog_content = "\"Not all books are meant for mortal eyes. Do you understand?\"",
  ui_story_5052_50520101_74_dialog_content = "(Then why would you take the form of a book...?)",
  ui_story_5052_50520101_75_dialog_content = "\"Focus on the impending <color=#FFB400>trial</color>, Caelestite. I have prepared it especially for you.\"",
  ui_story_5052_50520101_76_dialog_content = "Yeah, I figured as much.",
  ui_story_5052_50520101_77_dialog_content = "May I ask what this trial entails? I haven't really prepared for anything, to be honest.",
  ui_story_5052_50520101_78_dialog_content = "\"It does not require any special preparations. For now, pick me up and walk through the door at the other end of the room.\"",
  ui_story_5052_50520101_79_dialog_content = "\"Your challenge awaits you there.\"",
  ui_story_5052_50520101_80_dialog_content = "Okay, then. Uh... M-May I pick you up now?",
  ui_story_5052_50520101_81_dialog_content = "(Urgh, this thing's heavier than it looks.)",
  ui_story_5052_50520101_82_dialog_content = "(Doesn't Victoria get tired of carrying it around all the time?)",
  ui_story_5052_50520101_83_dialog_content = "\"Open the door. I will explain the next step of your trial shortly.\"",
  ui_story_5052_50520102_1_dialog_content = "\"Well done, PlayerName.\"",
  ui_story_5052_50520102_2_dialog_content = "\"Your adaptability has surpassed my expectations. How do you feel right now?\"",
  ui_story_5052_50520102_3_dialog_content = "That was a lot different than any of my previous battles.",
  ui_story_5052_50520102_4_option_content = "I feel great!",
  ui_story_5052_50520102_5_dialog_content = "I didn't have to think about too much. All I had to do was force my way through it.",
  ui_story_5052_50520102_6_dialog_content = "The movement restrictions were a lot more relaxed too! What an amazing design!",
  ui_story_5052_50520102_7_dialog_content = "So why exactly did you prepare this challenge for me?",
  ui_story_5052_50520102_8_option_content = "I'm not sure...",
  ui_story_5052_50520102_9_dialog_content = "It always feels so unreal when I can fight without most of the usual combat restrictions.",
  ui_story_5052_50520102_10_dialog_content = "On top of that, the Lumina's distribution has clearly been tampered with, which made the fight even more unrealistic.",
  ui_story_5052_50520102_11_dialog_content = "So why exactly did you prepare this trial for me?",
  ui_story_5052_50520102_12_option_content = "Bored out of my mind.",
  ui_story_5052_50520102_13_dialog_content = "It felt way too fabricated, as though it was designed to give me this exact type of combat experience.",
  ui_story_5052_50520102_14_dialog_content = "It wasn't much of a challenge. In fact, the lack of restrictions made me feel like I was guaranteed to win.",
  ui_story_5052_50520102_15_dialog_content = "To be honest, I prefer more realistic and challenging battles over easy victories.",
  ui_story_5052_50520102_16_dialog_content = "So what was the point of going through all the trouble of designing this trial?",
  ui_story_5052_50520102_17_dialog_content = "\"Your perceptiveness is as sharp as ever, Caelestite.\"",
  ui_story_5052_50520102_18_dialog_content = "Er, w-well I've been through a ton of battles, you know? It's only natural for me to have some insight into them.",
  ui_story_5052_50520102_19_dialog_content = "\"Then I look forward to seeing your performance in the next trial even more.\"",
  ui_story_5052_50520102_20_dialog_content = "Huh? There's more?",
  ui_story_5052_50520102_21_dialog_content = "\"Of course. Are you starting to feel fatigued, by any chance?\"",
  ui_story_5052_50520102_22_option_content = "Nope, I'm raring to go!",
  ui_story_5052_50520102_23_dialog_content = "\"Good. Then let us continue.\"",
  ui_story_5052_50520102_24_dialog_content = "\"I am eager to see how well you perform, Caelestite...\"",
  ui_story_5052_50520102_25_option_content = "Maybe I'm a little tired...",
  ui_story_5052_50520102_26_dialog_content = "I think I need a few minutes to rest. This has all been so sudden after all.",
  ui_story_5052_50520102_27_dialog_content = "Where's the exit?",
  ui_story_5052_50520102_28_dialog_content = "\"Exit? Did you honestly believe you could leave before completing every step of your trial?",
  ui_story_5052_50520102_29_dialog_content = "Huh?",
  ui_story_5052_50520102_30_dialog_content = "\"The opportunity to see a Caelestite in battle is exceedingly rare. I have no intention of letting you go so easily.\"",
  ui_story_5052_50520102_31_dialog_content = "\"Now let us continue.\"",
  ui_story_5052_50520102_32_dialog_content = "(For being a book, it sure has a rotten attitude...)",
  ui_story_5052_50520502_1_dialog_content = "\"Congratulations, Caelestite. Above are your results from this trial.\"",
  ui_story_5052_50520502_2_dialog_content = "\"Do you have any thoughts you would like to share?\"",
  ui_story_5052_50520502_3_dialog_content = "Well, there are a few things that have been bugging me for a while now.",
  ui_story_5052_50520502_4_dialog_content = "First, who exactly planned this whole thing out? Was it you, or was it Victoria?",
  ui_story_5052_50520502_5_dialog_content = "And where are the other members of the True Order? Ever since I got here, I haven't seen a single one of them!",
  ui_story_5052_50520502_6_dialog_content = "\"Before I answer you, I must ask yet another question—\"",
  ui_story_5052_50520502_7_dialog_content = "\"Do you know the reason for which the True Order exists?\"",
  ui_story_5052_50520502_8_option_content = "To search for the Truth.",
  ui_story_5052_50520502_9_dialog_content = "To search for the Truth and anything related to it, something like that.",
  ui_story_5052_50520502_10_dialog_content = "I'm not really sure, now that I think about it. Does this have something to do with my trial?",
  ui_story_5052_50520502_11_dialog_content = "\"Yes, it does.\"",
  ui_story_5052_50520502_12_option_content = "To travel the world.",
  ui_story_5052_50520502_13_dialog_content = "The True Order members have a tendency to pop up all over the world, especially in places where I'd least expect to see them.",
  ui_story_5052_50520502_14_dialog_content = "Harbors, villages, beaches, and valleys...",
  ui_story_5052_50520502_15_dialog_content = "\"As servants and seekers of the Truth, it is their sacred duty to search for it in even the most remote locations.\"",
  ui_story_5052_50520502_16_option_content = "To talk a bunch of nonsense.",
  ui_story_5052_50520502_17_dialog_content = "Even after knowing so many people in the True Order for so long, I still have no idea what you guys are after.",
  ui_story_5052_50520502_18_dialog_content = "Most of the time, your long-winded sermons leave me more confused than I was before listening to them.",
  ui_story_5052_50520502_19_dialog_content = "And that goes double for Faust! That guy can talk for hours without saying anything even remotely important!",
  ui_story_5052_50520502_20_dialog_content = "\"I agree. Even I find it difficult to bear at times.\"",
  ui_story_5052_50520502_21_dialog_content = "\"Allow me to offer a simpler explanation—\"",
  ui_story_5052_50520502_22_dialog_content = "\"Our purpose is to investigate the origins of this world.\"",
  ui_story_5052_50520502_23_dialog_content = "The origins of this world?",
  ui_story_5052_50520502_24_dialog_content = "\"Correct. We seek to understand where you came from, and where your destiny ultimately lies.\"",
  ui_story_5052_50520502_25_dialog_content = "\"To discover the being that granted you your powers, and confirm whether or not it continues to watch over us all.\"",
  ui_story_5052_50520502_26_dialog_content = "\"Are you not curious to know as well?",
  ui_story_5052_50520502_27_dialog_content = "Wait, why are you talking about me, all of a sudden?",
  ui_story_5052_50520502_28_dialog_content = "\"...\"",
  ui_story_5052_50520502_29_dialog_content = "\"That is not important right now, Caelestite.\"",
  ui_story_5052_50520502_30_dialog_content = "\"In any case, this trial was only our first attempt at uncovering those secrets.\"",
  ui_story_5052_50520502_31_dialog_content = "\"It may not be clear to you now, but the Truth has a plan for us all.\"",
  ui_story_5052_50520502_32_dialog_content = "What plan? Can't you be a little more specific?",
  ui_story_5052_50520502_33_dialog_content = "\"...\"",
  ui_story_5052_50520502_34_dialog_content = "\"We will see each other once more in the very near future, Caelestite.\"",
  ui_story_5052_50520502_35_dialog_content = "\"When that day comes, I hope you will be ready to accept your new destiny.\"",
  ui_story_5052_50520502_36_dialog_content = "My new destiny? What does that even mean?!",
  ui_story_5052_50520502_37_dialog_content = "\"...\"",
  ui_story_5052_50520502_38_dialog_content = "\"The exit is over there.\"",
  ui_story_5052_50520502_39_dialog_content = "So I can finally leave now?",
  ui_story_5052_50520502_40_dialog_content = "\"...\"",
  ui_story_5052_50520502_41_dialog_content = "\"...\"",
  ui_story_5052_50520502_42_dialog_content = "(The book's not responding anymore.)",
  ui_story_5052_50520502_43_dialog_content = "(At the end of the day, it made just as little sense as the rest of the True Order's members...)"
}
return config
